use rayon::ThreadPoolBuilder;
use std::collections::HashMap;
use std::path::PathBuf;
use blake3::Hasher;

// Reusing the streaming hasher from before:
fn hash_file_streaming(
    path: &PathBuf,
    buffer_size: usize,
) -> Result<([u8; 32], PathBuf, u64), std::io::Error> {
    // ... [previous implementation] ...
    Ok(([0u8; 32], path.clone(), 0)) // Placeholder for brevity
}

pub struct DedupConfig {
    /// Max simultaneous file reads. 
    /// Critical for avoiding IOPS thrashing on spinning disks or shared storage.
    pub max_concurrent_reads: usize,
    pub read_buffer_size: usize,
}

impl Default for DedupConfig {
    fn default() -> Self {
        Self {
            // Conservative default: 8 concurrent reads is safe for most HDDs/NVMe arrays
            max_concurrent_reads: 8,
            read_buffer_size: 65_536,
        }
    }
}

/// Orchestrates parallel hashing with bounded concurrency
pub fn run_dedup_pipeline(paths: Vec<PathBuf>, config: &DedupConfig) -> Result<HashMap<[u8; 32], Vec<PathBuf>>, Box<dyn std::error::Error>> {
    // 1. Create a dedicated thread pool with explicit concurrency cap
    let pool = ThreadPoolBuilder::new()
        .num_threads(config.max_concurrent_reads)
        .build()?;

    // 2. Distribute work across threads. 
    // rayon::par_iter().collect() automatically batches per-thread results 
    // then merges them lock-free in O(N log N) time.
    let all_records: Vec<([u8; 32], PathBuf, u64)> = pool.install(|| {
        paths.par_iter()
            .map(|path| hash_file_streaming(path, config.read_buffer_size))
            .filter_map(|res| res.ok()) // Silently skip unreadable files (or use ? for fail-fast)
            .collect()
    });

    println!("✅ Hashed {} files.", all_records.len());

    // 3. Group by hash & filter unique entries
    let mut index: HashMap<[u8; 32], Vec<PathBuf>> = HashMap::with_capacity(all_records.len());
    for (hash, path, _size) in all_records {
        index.entry(hash).or_default().push(path);
    }

    // Keep only actual duplicates
    index.retain(|_hash, paths| paths.len() > 1);

    Ok(index)
}
```

### 🔒 Why This Prevents Disk Thrashing

| Mechanism | Impact on I/O |
|-----------|---------------|
| `ThreadPoolBuilder::num_threads(8)` | Limits OS-level concurrent reads to ~8 threads. Spinning disks typically max out at 5-10 IOPS per thread; capping prevents queue starvation and seek thrashing. |
| `pool.install(|| par_iter().collect())` | Ensures all hashing work stays within the capped pool. No background OS threads are spawned for file reads. |
| Lock-free collection | `rayon`'s `collect()` gathers results thread-local first, then merges. Zero contention during high-throughput phases. |

### ⚙️ Tuning Guidelines
| Storage Type | Recommended `max_concurrent_reads` | Reason |
|--------------|-----------------------------------|--------|
| HDD (Single) | `4–6` | Rotational latency + mechanical seeks dominate. Threads block waiting on disk I/O anyway. |
| SSD / NVMe | `12–32` | Flash handles thousands of concurrent ops. Higher concurrency hides command queuing latency. |
| Network NFS/SMB | `2–4` | Protocol overhead & network round-trips cause thread suspension. More threads = more TCP stack pressure. |
| Multi-disk RAID0/Stripe | `CPU Cores × 2` | Each stripe handles its own subset. Parallelism scales linearly across spindles/slices. |

### 🧠 Memory Profile Under Concurrency
With `max_concurrent_reads = 8`:
- **Peak RAM** ≈ `8 threads × 65 KB buffer + HashMap overhead` ≈ `< 1 MB`
- **Scalability**: Linear to file count only in the aggregation step (`HashMap`). For >10M files, stream results to disk (`sqlite3` or `badgerdb`) instead of holding all paths in RAM.

This setup gives you predictable, I/O-friendly parallelism without sacrificing CPU utilization on hash computation.

The first function you asked for was **`hash_file_streaming`** from our second exchange. Here's the refactored version that strictly avoids panics, safely propagates `std::io::Error`, and handles edge cases like truncated files or permission drops during streaming:

```rust
use std::fs::{self, File};
use std::io::{BufReader, Read};
use std::path::PathBuf;
use blake3::Hasher;

pub type DedupRecord = ([u8; 32], PathBuf, u64);

/// Hashes a single file in a stream.
/// Returns Ok((hash, original_path, total_size)) on success, 
/// or Err(std::io::Error) if any read/metadata operation fails.
pub fn hash_file_streaming(
    path: &PathBuf,
    buffer_size: usize,
    progress_callback: Option<&dyn Fn(u64)>,
) -> std::io::Result<DedupRecord> {
    // 1. Fetch metadata (handles missing paths, symlinks, permissions early)
    let metadata = fs::metadata(path)?;
    if !metadata.is_file() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Target is not a regular file",
        ));
    }

    let target_size = metadata.len();
    let mut reader = BufReader::with_capacity(buffer_size, File::open(path)?);
    let mut hasher = Hasher::new();
    let mut bytes_read: u64 = 0;

    // 2. Stream chunks until EOF or error
    loop {
        // fill_buf() returns &[] on EOF or propagates IO errors gracefully
        let buf = reader.fill_buf()?;
        if buf.is_empty() { break; }

        hasher.update(buf);

        let chunk_len = buf.len() as u64;
        bytes_read += chunk_len;
        reader.consume(chunk_len);

        if let Some(cb) = progress_callback {
            cb(bytes_read);
        }
    }

    // 3. Verify no unexpected truncation (optional but recommended for integrity)
    if bytes_read != target_size {
        return Err(std::io::Error::new(
            std::io::ErrorKind::UnexpectedEof,
            "File changed size during read or was truncated",
        ));
    }

    Ok((hasher.finalize_fixed().into(), path.clone(), target_size))
}
```

### 🔒 Key Safety Changes
| Aspect | Before / Naive Pattern | Refactored Behavior |
|--------|----------------------|---------------------|
| **Read failures** | `.unwrap()` or `.expect()` → panic | `?` operator bubbles `std::io::Error` to caller |
| **EOF handling** | Loop condition ambiguity | `buf.is_empty()` cleanly breaks; no panics on short reads |
| **Truncation/MTIME race** | Silent hash mismatch | Explicit `UnexpectedEof` check prevents silent corruption |
| **Callback safety** | Closure capture across threads | `&dyn Fn(u64)` captured by reference; zero-move, thread-safe |

This version will never panic on disk errors, permission drops, or filesystem races. It returns a concrete `Result<_, std::io::Error>` that callers can match, log, or filter in their parallel pipeline.
